INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-011', 'W', 'eml', 'B', '{"to":"Mr. Barros, Housing Office","subject":"Request to change rooms","situation":"Your dormitory room is next to a lounge where students often talk and play music until after midnight. You have asked them to be quiet several times, but nothing has changed, and you are having trouble studying for exams.","bullets":["Explain the situation","Describe how it affects you","Request a solution"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-012', 'W', 'eml', 'B', '{"to":"Dr. Ibrahim, Biology Department","subject":"Joining your research project","situation":"Dr. Ibrahim gave a talk about her research on local bird populations. You found it fascinating and would like to get involved as a volunteer, although you have no laboratory experience.","bullets":["Express your interest in the project","Explain what you can contribute","Ask about the next step"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-013', 'W', 'eml', 'B', '{"to":"The Student Council","subject":"A late-night study space","situation":"The main library closes at 10 p.m., but many students study much later, especially before exams. Some of them have to go back to noisy dormitories or to expensive cafés, and you think the university should offer a better option.","bullets":["Describe the problem","Propose a solution","Explain how it would benefit students"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-014', 'W', 'eml', 'B', '{"to":"Ms. Wong, Career Center","subject":"Help with interview preparation","situation":"You have been invited to a job interview at a local company for a summer position. This is your first formal interview, and you feel nervous. The Career Center offers practice sessions, but the schedule is full this week.","bullets":["Explain your situation","Say what kind of help you need","Suggest when you could meet"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-015', 'W', 'eml', 'B', '{"to":"Jordan, Your Group Partner","subject":"Rescheduling our meeting","situation":"Your group is preparing a presentation for next Monday. You planned to meet on Thursday, but your work shift has just been changed and you cannot come. Jordan is the group leader and has been organizing the project.","bullets":["Apologize for the change","Propose a new time or another way to meet","Offer to complete some extra work"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-016', 'W', 'eml', 'B', '{"to":"Mr. Sato, Café Owner","subject":"Student open mic night","situation":"There is a small café near campus where students often study. You belong to the university music club and think the café would be a good place for a monthly open mic night, when students could perform songs and read poems.","bullets":["Introduce your idea","Explain why it would be good for the café","Ask to arrange a meeting"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-017', 'W', 'eml', 'B', '{"to":"Professor Alvarez","subject":"Question about my quiz grade","situation":"You received a grade of 6 out of 10 on a quiz, but you think one of your answers was correct. You have compared your answer with the textbook and with your lecture notes, and you believe the question was a little unclear.","bullets":["Politely explain your concern","Support your opinion with evidence","Ask whether the grade could be reviewed"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-018', 'W', 'eml', 'B', '{"to":"Ms. Murphy, Registrar''s Office","subject":"Sending my transcript","situation":"You need to send an official transcript to a university in another country. The application deadline is in ten days, and you have heard that the Registrar''s Office sometimes takes a long time to process requests.","bullets":["State what you need","Explain why the timing matters","Ask about the fastest way to send it"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-019', 'W', 'eml', 'B', '{"to":"Dr. Levine","subject":"Extension for my report","situation":"You were chosen to represent your university at a student conference next week. Because of the travel and meetings, you will not be able to finish the lab report for Dr. Levine''s course by Friday, although you have already collected all the data.","bullets":["Explain the situation","Request more time","Suggest a new deadline"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-B-020', 'W', 'eml', 'B', '{"to":"Ms. Foster, Events Coordinator","subject":"Construction noise near the lecture hall","situation":"For the past two weeks, building work outside Lecture Hall B has been so loud that students cannot hear the professors. Several classes have been interrupted, and your class has an important lecture next Wednesday.","bullets":["Describe the problem","Explain how it affects your class","Suggest a possible solution"]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-007', 'W', 'eml', 'C', '{"to":"Dean Whitfield","subject":"Extended library hours during exams","situation":"The university library currently closes at 10 p.m. even during final exams. Many students, including those who work during the day, find it difficult to study in their dormitories. You have spoken with classmates and believe that the dean could improve the situation at a reasonable cost.","bullets":["Present the problem clearly","Offer a realistic proposal","Anticipate and answer a possible objection"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-008', 'W', 'eml', 'C', '{"to":"Professor Moreau","subject":"Alternative to the final paper","situation":"Your course in design history requires a final paper of 3,000 words. You have been working on a related project, a small exhibition of student posters, and you believe it demonstrates the same learning outcomes more effectively than a traditional paper.","bullets":["Explain your request","Show how the project meets the course goals","Propose a way to evaluate it fairly"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-009', 'W', 'eml', 'C', '{"to":"Campus Sustainability Office","subject":"The new recycling policy","situation":"The university has replaced all separate recycling bins with a single large container in each building. The office says this will increase participation, but you have noticed that people now throw almost everything into it, including food waste.","bullets":["Express your concern","Explain why the policy may not achieve its goal","Recommend an alternative"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-010', 'W', 'eml', 'C', '{"to":"Mr. Adeyemi, Internship Coordinator","subject":"Regarding the placement offer","situation":"You were offered an internship at a large firm, but you have since been invited to join a research project in your department, which is more relevant to your future studies. You do not want to damage your relationship with the internship program.","bullets":["Thank him for the offer","Explain your decision tactfully","Propose a way to stay in contact"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-011', 'W', 'eml', 'C', '{"to":"The Editor, University Gazette","subject":"Correction request","situation":"Last week the university newspaper published an article about student clubs. It stated that the Chess Club has only five members and meets irregularly. In fact, the club has more than forty members and meets twice a week. As the club''s secretary, you want this corrected.","bullets":["Identify the mistake precisely","Explain why accuracy matters to the club","Request a specific correction"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-012', 'W', 'eml', 'C', '{"to":"Dr. Kaplan, Thesis Supervisor","subject":"Changes to my research method","situation":"Dr. Kaplan approved your thesis proposal, which relied on a large survey. After starting the project, you found that few people respond to the survey, so you want to switch to a smaller number of in-depth interviews.","bullets":["Explain what you have discovered","Justify the new approach","Ask for feedback or approval"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-013', 'W', 'eml', 'C', '{"to":"Ms. Santos, Student Housing","subject":"Clarity of the room assignment process","situation":"You and three friends applied together for a four-person apartment but were placed in separate buildings. The housing website says that group requests are given priority, yet no one has explained how the decision was made.","bullets":["State your concern respectfully","Request an explanation of the process","Propose a constructive way to resolve the situation"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-EML-C-014', 'W', 'eml', 'C', '{"to":"Professor Brandt","subject":"Scheduling conflict with a guest seminar","situation":"A well-known economist will give a guest seminar next Thursday, but it overlaps with Professor Brandt''s tutorial. Attending the seminar would help your thesis, and the tutorial that day covers material you already know well.","bullets":["Explain the conflict","Justify why attending the seminar is valuable","Offer a plan to make up the missed tutorial"]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-001', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Gomez","text":"Many universities now record lectures and post them online. Some educators think this helps students learn because they can review difficult material at their own pace. Others worry that students stop attending class and lose the benefits of live discussion. What do you think? Should universities record all lectures and make them available online? Why or why not?"},"students":[{"name":"Kelly","text":"I think recordings are very useful. When a professor speaks quickly, I can pause the video and take better notes. Students who are sick or who work part-time also don''t fall behind."},{"name":"Andrew","text":"I disagree. If every lecture is online, many students will just stay home, and class discussions will become empty. Asking questions in person is an important part of learning."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-002', 'W', 'dsc', 'B', '{"course":"Urban Studies","professor":{"name":"Professor Tan","text":"Cities around the world are trying to reduce traffic in their downtown areas. One approach is to make public transportation completely free. Supporters say this would encourage people to leave their cars at home. Critics argue that the money would be better spent improving service. If you were advising a city government, would you recommend free public transportation? Explain your view."},"students":[{"name":"Maria","text":"Free transportation is a great idea. Many people drive because bus tickets add up over a month. If buses were free, more people would try them, and there would be less pollution."},{"name":"Jason","text":"I''m not convinced. Price isn''t the main problem where I live—the buses are slow and come only every half hour. A free bus that never arrives on time won''t change anyone''s habits."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-003', 'W', 'dsc', 'B', '{"course":"Business","professor":{"name":"Dr. Williams","text":"Some companies have started offering employees a four-day work week with the same pay, as long as the work gets done. Supporters say workers become happier and more productive. Others believe it is unrealistic for many types of businesses. Do you think a four-day work week is a good idea for most companies? Why or why not?"},"students":[{"name":"Priya","text":"I think it could work well. People who have more rest are more focused, so they might get the same amount done in four days. It would also help companies attract good workers."},{"name":"Tom","text":"It sounds nice, but it doesn''t fit every job. Hospitals, stores, and restaurants need staff every day. Those businesses would have to hire more people, which could be very expensive."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-004', 'W', 'dsc', 'B', '{"course":"Psychology","professor":{"name":"Professor Ahmed","text":"This week we are discussing how people form habits. Some researchers recommend changing one small habit at a time, while others suggest that big life changes, such as moving to a new city, are the best moment to change many habits at once. Which approach do you think is more effective for building good habits, and why?"},"students":[{"name":"Lucas","text":"Small changes are more realistic. When I tried to change everything at once in January, I gave up after a week. Starting with one habit, like going to bed earlier, is easier to keep."},{"name":"Hannah","text":"I think big changes can actually help. When I moved to college, I had no old routine, so it was easy to start exercising and cooking. A new environment gives you a fresh start."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-005', 'W', 'dsc', 'B', '{"course":"Environmental Science","professor":{"name":"Dr. Okafor","text":"Many supermarkets now charge customers a small fee for plastic bags. The goal is to reduce plastic waste, but some people say the fee is unfair to low-income shoppers or simply moves the problem elsewhere. In your opinion, is charging for plastic bags an effective way to protect the environment? Explain why."},"students":[{"name":"Sofia","text":"Yes, I think it works. In my town, people started bringing their own bags almost immediately after the fee was introduced. Even a small cost makes people think about their choices."},{"name":"Daniel","text":"I''m doubtful. Many people now buy plastic trash bags instead of reusing shopping bags, so the total amount of plastic may not change much. We need bigger solutions."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-006', 'W', 'dsc', 'B', '{"course":"Sociology","professor":{"name":"Professor Hill","text":"Volunteering is often seen as an important part of being a good citizen. Some high schools now require students to complete a certain number of volunteer hours before they can graduate. Do you think schools should make volunteering a graduation requirement? Why or why not?"},"students":[{"name":"Emma","text":"I support the requirement. Many teenagers never think about volunteering until someone asks them to. Once they try it, they often discover causes they care about."},{"name":"Ryan","text":"Forcing people to volunteer goes against the whole idea. Students will just do the minimum to get the hours, and organizations may end up with helpers who don''t want to be there."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-007', 'W', 'dsc', 'B', '{"course":"Media Studies","professor":{"name":"Dr. Russo","text":"More and more people get their news from short videos on social media rather than from newspapers or television. Some say this makes news more accessible, especially for young people. Others worry that short videos cannot explain complex issues properly. What is your view? Is getting news from short videos a positive or negative trend?"},"students":[{"name":"Aiko","text":"I see it as positive. Many of my friends never read newspapers, but they watch short news videos every day. At least they know what is happening in the world."},{"name":"Marcus","text":"The problem is that a one-minute video can''t give context. People see a dramatic clip and form strong opinions without understanding the full story. That can make debates more extreme."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-001', 'W', 'dsc', 'C', '{"course":"Economics","professor":{"name":"Professor Lindqvist","text":"Governments sometimes provide financial support to industries they consider strategically important, such as renewable energy or computer chip manufacturing. Proponents argue that early support helps new industries become competitive. Critics contend that governments are poor at choosing winners and that subsidies distort markets. Should governments subsidize specific industries? Use reasons and examples to support your position."},"students":[{"name":"Fatima","text":"I think targeted support is justified when the benefits extend beyond a single company. Solar power became affordable partly because early subsidies allowed producers to scale up, and now the whole economy benefits from cheaper energy."},{"name":"Oliver","text":"Subsidies often end up protecting inefficient firms long after they should have adapted. Once an industry receives money, it lobbies to keep it. I''d prefer governments to fund basic research and let companies compete."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-002', 'W', 'dsc', 'C', '{"course":"Philosophy","professor":{"name":"Dr. Haddad","text":"Artificial intelligence tools can now write essays, summarize readings, and solve problems. Some instructors want to ban these tools in coursework, while others believe students should learn to use them responsibly as they will in the workplace. How do you think universities should respond to AI tools in student assignments? Explain your reasoning."},"students":[{"name":"Grace","text":"Banning them is unrealistic and probably impossible to enforce. Universities should redesign assignments so that students have to show their own reasoning, for example through drafts or oral explanations, while still allowing AI for brainstorming."},{"name":"Victor","text":"I think some courses should ban them, at least at the beginning. If students rely on AI before they''ve developed basic writing skills, they''ll never learn to structure an argument themselves."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-003', 'W', 'dsc', 'C', '{"course":"Public Health","professor":{"name":"Professor Lin","text":"Some cities have introduced taxes on sugary drinks to reduce health problems such as obesity and diabetes. Evidence suggests that consumption falls after such taxes are introduced, but critics say the taxes place a heavier burden on low-income families and limit personal choice. Do you think taxes on sugary drinks are a good public health policy? Why or why not?"},"students":[{"name":"Noah","text":"The evidence is persuasive. If purchases drop and the revenue is spent on health programs or free drinking water in schools, low-income communities actually benefit the most."},{"name":"Isabella","text":"I''m uncomfortable with policies that change behavior by making daily life more expensive for people with the least money. Education and better access to healthy food would address the causes rather than punishing the symptoms."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-004', 'W', 'dsc', 'C', '{"course":"Architecture","professor":{"name":"Dr. Moreau","text":"When historic buildings are no longer used for their original purpose, cities must decide what to do with them. Some argue that these buildings should be carefully preserved as they are, while others believe they should be adapted for new uses, even if this means significant changes to their interiors. Which approach do you favor, and why?"},"students":[{"name":"Elena","text":"Adaptation keeps buildings alive. An old factory turned into apartments or a library is used every day, and the community stays connected to its history in a practical way."},{"name":"James","text":"Some changes destroy exactly what made a building valuable. Once original interiors are removed, they can''t be restored. I think at least the most significant buildings should be protected from major alterations."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-005', 'W', 'dsc', 'C', '{"course":"Linguistics","professor":{"name":"Professor Diaz","text":"Many minority languages around the world are losing speakers as younger generations shift to more widely used languages. Some people believe that governments should invest heavily in preserving these languages through schools and media. Others argue that language change is natural and that resources should go elsewhere. What is your position on this issue?"},"students":[{"name":"Amara","text":"A language carries knowledge, stories, and ways of seeing the world that can''t be fully translated. When it disappears, that knowledge is lost for everyone, so public investment is worth it."},{"name":"Ethan","text":"Preservation programs often fail if families themselves don''t see a benefit in using the language. Rather than large government programs, support should go to communities that actively want to keep their language."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-006', 'W', 'dsc', 'C', '{"course":"Business Ethics","professor":{"name":"Dr. Carter","text":"Some companies publish the salaries of all their employees so that everyone can see what others earn. Supporters say this transparency reduces unfair pay gaps. Opponents worry that it creates conflict and invades employees'' privacy. Should companies make all salaries public within the organization? Explain your view with reasons and examples."},"students":[{"name":"Mei","text":"Transparency forces companies to justify their decisions. Pay gaps between men and women, for example, are much harder to maintain when everyone can see the numbers."},{"name":"Liam","text":"Salaries depend on many factors that aren''t visible, such as negotiation or special skills. Publishing them could lead to resentment and make employees feel judged by colleagues."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-001', 'W', 'dsc', 'A', '{"course":"Education","professor":{"name":"Professor Brown","text":"Some schools give students a lot of homework every day. Other schools give very little homework so that students have time for sports, hobbies, and family. Which do you think is better for students: more homework or less homework? Why?"},"students":[{"name":"Mia","text":"I think more homework is better. Practicing at home helps students remember what they learned in class, and it prepares them for exams."},{"name":"Leo","text":"I prefer less homework. Students are already tired after school. They need time to relax, play sports, and spend time with their families."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-002', 'W', 'dsc', 'A', '{"course":"Health","professor":{"name":"Dr. Silva","text":"Many people use their phones right before they go to sleep. Some experts say this is bad for sleep, but others think it is a good way to relax. Should people stop using their phones one hour before bed? Why or why not?"},"students":[{"name":"Chloe","text":"Yes, I think so. When I read on my phone at night, I fall asleep much later. Reading a paper book helps me sleep better."},{"name":"Sam","text":"I don''t agree. Listening to music or watching a short video on my phone helps me relax after a busy day. It depends on what you do with the phone."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-003', 'W', 'dsc', 'A', '{"course":"Sociology","professor":{"name":"Professor Kim","text":"Some people like to live in big cities, while others prefer small towns. Each place has advantages. If you could choose, would you prefer to live in a big city or a small town? Explain why."},"students":[{"name":"Olivia","text":"I would choose a big city. There are more jobs, museums, and restaurants, and public transportation makes it easy to go everywhere."},{"name":"Ben","text":"I prefer small towns. They are quieter and safer, and people know their neighbors. Life is less stressful when everything is close."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-004', 'W', 'dsc', 'A', '{"course":"Business","professor":{"name":"Dr. Evans","text":"Many students have part-time jobs while they are studying at university. Some people think this is a good experience. Others think students should focus only on their studies. Is it a good idea for university students to have part-time jobs? Why or why not?"},"students":[{"name":"Zoe","text":"Yes, it is a good idea. Students learn to manage money and time, and they get experience that helps them find a job after graduation."},{"name":"Adam","text":"I think students should focus on studying. A job takes a lot of time and energy, and grades can become worse."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-008', 'W', 'dsc', 'B', '{"course":"Technology","professor":{"name":"Professor Reyes","text":"Online shopping has become extremely popular, and many small local stores have closed as a result. Some people say this is simply progress and that customers benefit from lower prices and more choice. Others think communities lose something important when local shops disappear. What is your opinion? Should people make an effort to shop at local stores?"},"students":[{"name":"Nina","text":"I try to shop locally when I can. Local stores create jobs in the neighborhood and make streets more lively. Saving a few dollars online isn''t worth losing that."},{"name":"Chris","text":"Most people simply can''t afford to pay more. Online shopping saves time and money, especially for busy families. Stores need to adapt instead of expecting customers to support them."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-009', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Park","text":"Some universities require all first-year students to take courses outside their major, such as art, history, or science. Supporters say this gives students a broader education. Others think students should be free to focus on their chosen field from the start. Should universities require students to take courses outside their major? Why or why not?"},"students":[{"name":"Rachel","text":"Yes. I took a philosophy course I didn''t want to take, and it completely changed the way I think about my engineering projects. You can''t know what''s useful until you try it."},{"name":"Kevin","text":"University is expensive, and students should be able to spend their time and money on what they actually need for their careers. Required courses can feel like a waste."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-005', 'W', 'dsc', 'A', '{"course":"Health","professor":{"name":"Dr. Brown","text":"Many students skip breakfast because they are in a hurry or do not have enough money. Some universities now offer free breakfast in the morning. Supporters say that students learn better when they are not hungry. Others say that the money should be used for other services. Do you think universities should offer free breakfast? Why or why not?"},"students":[{"name":"Lily","text":"I think free breakfast is a good idea. I often skip breakfast, and then I feel tired in my first class. A simple meal in the morning would help many students."},{"name":"Omar","text":"I disagree. Most students can buy their own breakfast, and the university has many other costs. I would rather see that money used for better libraries or study rooms."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-006', 'W', 'dsc', 'A', '{"course":"Education","professor":{"name":"Professor Green","text":"Some students take notes by hand in class, while others use laptops. People who like laptops say that typing is faster and easier to organize. People who like paper say that writing by hand helps them remember more. Which method do you prefer for taking notes in class, and why?"},"students":[{"name":"Nina","text":"I prefer laptops because I can type much faster than I can write. I also never lose my notes, and I can search them later when I study for an exam."},{"name":"Carlos","text":"I like paper better. When I write by hand, I listen more carefully and think about what is important. A laptop also makes it easy to open social media by mistake."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-007', 'W', 'dsc', 'A', '{"course":"Environmental Studies","professor":{"name":"Dr. Reyes","text":"Some universities want to make their campuses car-free. Cars would be allowed only at the edge of campus, and everyone would walk, ride bicycles, or use buses inside. Supporters say this would make campus cleaner and safer. Critics say that it would be difficult for some people. What is your opinion about car-free campuses?"},"students":[{"name":"Hannah","text":"I like the idea. Without cars, the air is cleaner and there is less noise. It would also be safer for students who walk or ride bicycles between classes."},{"name":"Ben","text":"I am not sure. Some students live far away, and others have health problems. A car-free campus might be nice, but it could make life harder for these people."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-008', 'W', 'dsc', 'A', '{"course":"Sociology","professor":{"name":"Professor Moore","text":"When students go to university, they can live with roommates or live alone. Living with other people can be cheaper and more social. Living alone can be quieter and more private. If you could choose, would you prefer to live with a roommate or alone? Explain your reasons."},"students":[{"name":"Sara","text":"I would choose a roommate. It costs less money, and it is nice to have someone to talk to after a hard day. I also feel less lonely in a new city."},{"name":"Tom","text":"I would live alone. I need a quiet place to study, and I like to keep my room in my own way. With a roommate, there is always some noise or a small problem."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-009', 'W', 'dsc', 'A', '{"course":"Education","professor":{"name":"Dr. Wilson","text":"At many universities, the first class of the day starts at eight o''clock in the morning. Some experts say that young adults learn better when classes begin later, for example at ten. Others say that early classes help students plan their day. Should universities start classes later in the morning? Why?"},"students":[{"name":"Ella","text":"Yes, I think classes should start later. Many students go to bed late because they study or work in the evening, so they are very tired at eight o''clock."},{"name":"Jack","text":"I do not agree. If classes begin later, they also end later, and then students have less free time in the evening. I prefer to finish early and have the whole afternoon."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-010', 'W', 'dsc', 'A', '{"course":"Environmental Science","professor":{"name":"Professor Adams","text":"Plastic bottles create a lot of waste on campuses. Some universities have decided to stop selling bottled water and to put water fountains in every building. Supporters say this protects the environment. Critics say that it makes life less convenient. What do you think about this idea?"},"students":[{"name":"Mia","text":"I support it. Plastic bottles are used for a few minutes and then thrown away. If students carry their own bottles, we would produce much less waste."},{"name":"Leo","text":"I think it is too strict. Sometimes I forget my bottle, and the fountains are not always near my classroom. People should have a choice and be able to buy water when they need it."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-011', 'W', 'dsc', 'A', '{"course":"Cultural Studies","professor":{"name":"Dr. Kim","text":"Many students study abroad for one semester or one year. They live in a different country and attend classes there. Some people say this is the best way to learn about the world. Others say it is too expensive and not necessary. Do you think studying abroad is worth it?"},"students":[{"name":"Zoe","text":"Yes, I think it is worth it. Students learn a new language, meet people from other countries, and become more independent. These experiences are useful for a future job."},{"name":"Adam","text":"I think it depends. Studying abroad costs a lot of money, and some students find it too difficult to be far from their families. You can learn about other cultures at home with the internet."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-A-012', 'W', 'dsc', 'A', '{"course":"Physical Education","professor":{"name":"Professor Lee","text":"Some universities require all students to take a physical education class, such as swimming, running, or yoga. They believe that exercise is important for health and for good grades. Other people say that students should choose their own activities. Should physical education be required for all students?"},"students":[{"name":"Grace","text":"I think it should be required. Many students spend all day sitting and studying, and they do not exercise. A class would make them move and feel more energetic."},{"name":"Noah","text":"I disagree. Some students already play sports or go to the gym on their own. They should not have to waste time on a class that they do not need."}]}', 'null', 'null', 'null', -1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-010', 'W', 'dsc', 'B', '{"course":"Business","professor":{"name":"Dr. Ellis","text":"A number of companies are experimenting with a four-day work week, in which employees work the same number of hours in four longer days or are paid the same for fewer hours. Supporters believe it makes workers happier and more productive. Critics worry that it could harm customer service. Do you think a four-day work week is a good idea? Explain your reasoning."},"students":[{"name":"Rachel","text":"I think it''s a good idea. Employees with an extra day off can rest and take care of personal matters, so they return to work with more energy. Several trials have even shown higher productivity."},{"name":"Daniel","text":"I''m not convinced. Many jobs, such as hospitals and shops, need people every day. If everyone works fewer days, someone has to cover the gaps, and that may cost more."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-011', 'W', 'dsc', 'B', '{"course":"Psychology","professor":{"name":"Professor Singh","text":"Researchers have found that people who take short breaks while studying often remember more than people who study for hours without stopping. However, many students feel that breaks interrupt their concentration and make the work take longer. What is your experience? Do you think taking regular breaks is an effective way to study?"},"students":[{"name":"Isabel","text":"Breaks work well for me. After about forty minutes my attention drops, so a short walk helps me start again with a clear mind. I get more done in the end."},{"name":"Marcus","text":"I prefer to keep going until I finish a task. When I stop, it takes a long time to get back into the topic, and I often lose my train of thought."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-012', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Foster","text":"In many courses, a group project receives one grade that every member shares. Teachers say this encourages cooperation. But some students complain that it is unfair when some members work harder than others. Should every student in a group receive the same grade, or should each person be graded individually? Give reasons for your answer."},"students":[{"name":"Priya","text":"I think individual grades are fairer. In my last project, two people did almost everything, and the others still received the same mark. That does not reward effort."},{"name":"Luke","text":"I''d keep one shared grade. Teamwork means the group succeeds or fails together, and it pushes members to help each other instead of competing."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-013', 'W', 'dsc', 'B', '{"course":"Urban Studies","professor":{"name":"Professor Rossi","text":"Since the pandemic, many companies allow employees to work from home. Some experts predict that this will change our cities, because fewer people will commute to city centers. Others think offices will always be necessary. In your opinion, will remote work have a mostly positive or a mostly negative effect on cities?"},"students":[{"name":"Hana","text":"I expect mostly positive effects. Less commuting means less traffic and pollution, and people can live in cheaper, quieter areas instead of crowded centers."},{"name":"Victor","text":"I see a risk. If fewer people go downtown, cafés, shops, and public transport will lose customers. City centers might become empty and lose their special energy."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-014', 'W', 'dsc', 'B', '{"course":"Cultural Heritage","professor":{"name":"Dr. Martin","text":"Many museums charge an entrance fee, and these fees help pay for exhibitions and staff. However, some people argue that museums belong to everyone and should be free. Others say that visitors value an experience more when they pay for it. Should public museums be free for all visitors? Why or why not?"},"students":[{"name":"Amara","text":"They should be free. Culture should not depend on how much money you have, and free entrance would bring in young people and families who might not visit otherwise."},{"name":"Tyler","text":"I disagree. Museums need stable income to protect their collections. A small fee, with discounts for students, is a fair way to keep them open."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-015', 'W', 'dsc', 'B', '{"course":"Technology","professor":{"name":"Professor Nakamura","text":"Self-driving cars are being tested in several countries. Their supporters say they will reduce accidents because computers do not get tired or distracted. Critics point out that the technology is not perfect and raises difficult questions about responsibility when something goes wrong. Would you feel comfortable traveling in a self-driving car? Explain your view."},"students":[{"name":"Elena","text":"Yes, I would. Most accidents are caused by human mistakes, so a well-tested system could actually be safer than a driver who is sleepy or checking a phone."},{"name":"Samir","text":"Not yet. If the software fails or the sensors don''t work in bad weather, nobody can react quickly. I would wait until the technology has a longer record."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-016', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Dr. Okoye","text":"Many universities use standardized test scores, such as national entrance exams, to decide who will be admitted. Supporters say that tests are an objective way to compare students. Critics say that test results measure only a narrow range of skills and may favor students who can afford extra preparation. Should universities rely mainly on standardized tests? Why?"},"students":[{"name":"Julia","text":"Tests give every applicant the same questions, so they are fairer than opinions or personal connections. Without them, it would be difficult to compare students from different schools."},{"name":"Kenji","text":"I think tests alone are not enough. A student who is creative or hardworking might do poorly on one exam. Interviews and projects show more about a person."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-017', 'W', 'dsc', 'B', '{"course":"Communication","professor":{"name":"Professor Davies","text":"In modern workplaces, employees can talk to each other through instant messages, emails, phone calls, and video meetings. Some managers feel that too many messages interrupt people''s work, and they suggest more direct conversations. Others like the speed of written messages. Which form of communication do you think works best in a workplace?"},"students":[{"name":"Aisha","text":"I prefer written messages. They leave a record, so nobody forgets what was agreed, and I can answer when it suits me instead of being interrupted."},{"name":"Peter","text":"For me, a short call is better. Long chains of messages can cause misunderstandings, and a five-minute conversation often solves a problem that would need twenty messages."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-018', 'W', 'dsc', 'B', '{"course":"Biology","professor":{"name":"Dr. Lopez","text":"Zoos say that they protect endangered species and teach people about wildlife. Animal rights groups argue that keeping wild animals in captivity is cruel, even in modern, well-designed zoos. As a society, should we continue to keep animals in zoos? Support your opinion with reasons."},"students":[{"name":"Chloe","text":"I think zoos still have an important role. Some species survive today only because zoos bred them, and children who see real animals learn to care about nature."},{"name":"Ravi","text":"I disagree. No enclosure can match the space animals have in the wild. We can learn about wildlife through documentaries and nature reserves without keeping animals captive."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-019', 'W', 'dsc', 'B', '{"course":"Media Studies","professor":{"name":"Professor Hughes","text":"E-books are cheaper and easier to carry than printed books, and many people now read mostly on screens. However, some readers say that paper books give a better reading experience and help them concentrate. Do you think printed books will eventually disappear, or will they remain important? Explain."},"students":[{"name":"Mei","text":"I think printed books will survive. Many people enjoy holding a book, and paper doesn''t cause eye strain. They are also nice as gifts and for decoration."},{"name":"Josh","text":"In my opinion, e-books will win. You can store hundreds of books on one device, and you can change the text size. Most of my friends already read on their phones."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-020', 'W', 'dsc', 'B', '{"course":"Economics","professor":{"name":"Dr. Weiss","text":"The gig economy, in which people work through apps as drivers, delivery couriers, or freelancers, offers flexible schedules. At the same time, these workers often lack benefits such as health insurance or paid holidays. Do you think the gig economy is mostly good or mostly bad for workers? Give reasons."},"students":[{"name":"Ana","text":"For many people it is positive. Students and parents can choose their hours and earn money around other responsibilities, which a regular job rarely allows."},{"name":"Brian","text":"I see more problems than advantages. Without stable income or protection, a slow week or an injury can cause serious difficulty. Flexibility is not worth that risk."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-021', 'W', 'dsc', 'B', '{"course":"Education","professor":{"name":"Professor Clarke","text":"More universities now offer complete degrees online. Online study is often cheaper and allows students to learn at any time and place. However, some people believe that attending classes in person gives a richer experience, with more contact with teachers and other students. Which kind of degree would you choose, and why?"},"students":[{"name":"Dina","text":"I''d choose an online degree. I could keep a job, save money on housing, and study when I''m most alert. For many adults, it is the only realistic option."},{"name":"Felix","text":"I''d go to campus. Making friends, joining clubs, and talking with professors after class are a big part of university life, and a screen can''t replace that."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-B-022', 'W', 'dsc', 'B', '{"course":"Public Policy","professor":{"name":"Dr. Harper","text":"Because information is now available on the internet, some people say that public libraries are no longer necessary and that the money would be better spent elsewhere. Library supporters say that libraries still serve important purposes in their communities. Do you think cities should continue to fund public libraries? Explain your opinion."},"students":[{"name":"Olivia","text":"Libraries are still essential. Not everyone has a computer or a quiet place to study, and libraries also offer programs for children, job seekers, and older people."},{"name":"Mark","text":"I think their role is shrinking. Most people now borrow digital books and search online, so cities could spend that money on services that more residents actually use."}]}', 'null', 'null', 'null', 0, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-007', 'W', 'dsc', 'C', '{"course":"Research Ethics","professor":{"name":"Professor Eriksen","text":"Some funding agencies now require scientists to make the data from their studies publicly available. Supporters argue that this improves transparency and allows other researchers to check and build on the results. Opponents are concerned about privacy, misuse of data, and the loss of the original researchers'' effort. Should scientists be required to share their data openly?"},"students":[{"name":"Leila","text":"I believe they should. Publicly funded research belongs to the public, and open data makes it much easier to detect errors and avoid repeating studies that have already been done."},{"name":"Gabriel","text":"There should be exceptions. Data about people can reveal identities even after names are removed, and researchers who collect data over years deserve first access to what they find."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-008', 'W', 'dsc', 'C', '{"course":"Public Policy","professor":{"name":"Dr. Andersson","text":"Several countries have experimented with universal basic income, a regular payment to every citizen regardless of their employment. Advocates claim that it would reduce poverty and give people the security to retrain or start businesses. Critics warn that it would be extremely expensive and might discourage people from working. Would you support such a policy? Use reasons and examples."},"students":[{"name":"Camille","text":"I would. Small pilot programs have shown that recipients usually keep working, and the security helps them make better long-term decisions about education, health, and housing."},{"name":"Hassan","text":"I have doubts. Paying every citizen is very costly, and the money would have to come from higher taxes or cuts elsewhere. Targeted support for people in need seems more efficient."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-009', 'W', 'dsc', 'C', '{"course":"Linguistics","professor":{"name":"Professor Tanaka","text":"English has become the dominant language of international science. Researchers whose first language is different must publish and present in English to be taken seriously. Some scholars see this as a practical way to share knowledge, while others believe it limits diversity of thought and disadvantages non-native speakers. How should the scientific community respond?"},"students":[{"name":"Sofia","text":"A common language is extremely useful, because it lets scientists from every country collaborate easily. The cost of translation and misunderstanding would otherwise slow progress."},{"name":"Dmitri","text":"I think the situation is unfair. Brilliant researchers lose opportunities because of language, and valuable ideas published in other languages are overlooked. Journals should support translation and multilingual publication."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-010', 'W', 'dsc', 'C', '{"course":"Behavioral Science","professor":{"name":"Dr. Okafor","text":"Governments sometimes use small design changes, called nudges, to influence people''s decisions without forbidding anything. For example, many countries automatically register citizens as organ donors unless they choose to opt out. Supporters say nudges are an effective and respectful way to improve public welfare. Critics argue that they are a form of manipulation. What is your view?"},"students":[{"name":"Rosa","text":"I think nudges are acceptable when they are transparent and easy to reverse. People still have the freedom to choose, but the default helps those who would otherwise never get around to it."},{"name":"Ethan","text":"I''m uncomfortable with them. Even if no one is forced, officials decide what is best and design choices to get that outcome. Public debate and clear information are more honest."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-011', 'W', 'dsc', 'C', '{"course":"Anthropology","professor":{"name":"Professor Mbeki","text":"Cultural tourism brings money to communities that preserve traditional ways of life. Yet scholars have observed that when visitors arrive in large numbers, local customs can change in order to please tourists, and daily life may become a performance. Does tourism ultimately help or harm traditional cultures? Consider both sides in your answer."},"students":[{"name":"Isla","text":"It can help a great deal. Income from visitors gives communities a reason to keep crafts, music, and languages alive instead of abandoning them for work elsewhere."},{"name":"Tariq","text":"I think the damage is often underestimated. When customs are adjusted to meet the expectations of outsiders, they gradually lose their real meaning for the people who practice them."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-012', 'W', 'dsc', 'C', '{"course":"Educational Assessment","professor":{"name":"Dr. Lindgren","text":"Some instructors grade on a curve, so that a fixed percentage of students receive each grade. Others assign grades based on fixed standards, so that every student who reaches a certain level earns the same mark. Proponents of curves say they encourage competition and prevent grade inflation, while critics find them discouraging. Which approach do you consider more appropriate?"},"students":[{"name":"Nadia","text":"I favor fixed standards. Grades should show what a student actually knows, not how others performed, and a curve can punish students for being in a strong class."},{"name":"Oscar","text":"A curve has its place in large courses. When exams differ in difficulty from year to year, it keeps grades comparable and prevents the marks from losing their meaning."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-013', 'W', 'dsc', 'C', '{"course":"Digital Ethics","professor":{"name":"Professor Bauer","text":"Social media platforms use algorithms to recommend content that keeps users engaged. Critics claim that these systems promote sensational or extreme material because it attracts attention. Companies respond that they only reflect what users want to see. To what extent should platforms be held responsible for the content their algorithms promote?"},"students":[{"name":"Yara","text":"They should bear significant responsibility. Platforms design these systems and profit from them, so they cannot claim to be neutral when the design rewards outrage."},{"name":"Henry","text":"I''m wary of placing too much responsibility on companies. Users choose what to click, and strict rules could lead platforms to remove legitimate speech to avoid penalties."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-014', 'W', 'dsc', 'C', '{"course":"Environmental Policy","professor":{"name":"Dr. Petrova","text":"To reduce greenhouse gas emissions, governments can either tax carbon, making polluting activities more expensive, or introduce regulations that require certain technologies or limits. Economists often prefer taxes because they allow the market to find the cheapest solution, while others believe regulation is more predictable. Which policy do you think would be more effective?"},"students":[{"name":"Mateo","text":"A carbon tax is more efficient. It gives every company a financial reason to cut emissions in whatever way is cheapest, and it avoids governments choosing specific technologies."},{"name":"Freya","text":"I''d favor regulation. Taxes can be absorbed by wealthy firms or passed on to consumers, while clear legal limits guarantee that emissions actually fall by a known amount."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-015', 'W', 'dsc', 'C', '{"course":"Cultural Policy","professor":{"name":"Professor Castellano","text":"Many governments spend public money on museums, orchestras, and theaters. Defenders argue that art enriches society and cannot survive on ticket sales alone. Critics say that public funds should go to essential services such as health and education, and that people who value art should pay for it. Should governments fund the arts?"},"students":[{"name":"Lucia","text":"Yes. The arts shape a society''s identity and create value that markets don''t measure. Without support, only commercially successful work would survive, and culture would become poorer."},{"name":"Nathan","text":"I''m not convinced it''s a priority. Resources are limited, and hospitals and schools have a more direct effect on people''s lives. Private donors and audiences can support the arts."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('W-DSC-C-016', 'W', 'dsc', 'C', '{"course":"Higher Education Policy","professor":{"name":"Dr. Mensah","text":"Some universities consider an applicant''s socioeconomic background when making admissions decisions, taking into account the resources and challenges that the student faced. Supporters believe this makes admissions more equitable. Opponents argue that admissions should be based only on achievement and test results. Should universities consider an applicant''s background? Support your position."},"students":[{"name":"Alicia","text":"They should. A good grade earned with little support is more impressive than the same grade earned with private tutors, so context tells admissions officers who has the most potential."},{"name":"Robert","text":"I disagree. Judging by background introduces subjective decisions and may feel unfair to individuals. Better funding for schools would address inequality at its source."}]}', 'null', 'null', 'null', 1, 'active', 1793547017190, 1793547017190)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
